	this.shape.graphics.f().s("#0033FF").ss(1,1,1).p("AB6AAQAAAzgkAjQgjAkgzAAQgyAAgjgkQgkgjAAgzQAAgyAkgjQAjgkAyAAQAzAAAjAkQAkAjAAAyg");
	this.shape.setTransform(48.7,-84.55);

	this.shape_1 = new cjs.Shape();
	this.shape_1.graphics.f("#0066FF").s().p("AhVBWQgjgjgBgzQABgyAjgjQAjgjAygBQAzABAjAjQAjAjAAAyQAAAzgjAjQgjAjgzAAQgyAAgjgjg");
