(lib.blower = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.kipas_blower.rotation = 0;
		this.kipas_blowerPutar = 0;
		
		this.nyala = function () {
		    const nilai1 = this.parent.kpsblr1.nilai;
		    const nilai2 = this.parent.kpsblr2.nilai;
		
		    // volt berdasarkan nilai terbesar
		    const volt = (Math.max(nilai1, nilai2) * Math.min(nilai1, nilai2)/3) ;
		
		    // Tentukan arah berdasarkan nilai yang lebih besar
		    if (nilai1 > nilai2 && nilai2 !=0) {
		        this.kipas_blowerPutar = volt; // putar kanan
				this.parent.hubungan("kpsblr2", 1);
		        
		    } else if (nilai2 > nilai1 && nilai1 !=0) {
		        this.kipas_blowerPutar = -volt; // putar kiri
				this.parent.hubungan("kpsblr1", 1);
		        
		    } else {
		        // Nilai sama tapi tidak 0 → tetap diam (opsional bisa diubah jadi berputar)
		        this.kipas_blowerPutar = 0;
		        this.parent.hubungan("kpsblr1", 0);
		        this.parent.hubungan("kpsblr2", 0);
		    }
		};
		
		// Update rotasi tiap frame
		createjs.Ticker.addEventListener("tick", () => {
		    this.nyala();
		    this.kipas_blower.rotation += this.kipas_blowerPutar;
			this.kipas_blower2.rotation += this.kipas_blowerPutar;
		});
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Layer_1
	this.kipas_blower2 = new lib.kipas_blower();
	this.kipas_blower2.name = "kipas_blower2";
	this.kipas_blower2.setTransform(-27.55,-62.7,0.4603,0.4603,0,0.585,0,0.3,-0.4);

	this.kipas_blower = new lib.kipas_blower();
	this.kipas_blower.name = "kipas_blower";
	this.kipas_blower.setTransform(38.8,-40.5,0.7549,0.7549,0,0.5883,0,0.4,-0.2);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.kipas_blower},{t:this.kipas_blower2}]}).wait(1));

	// Layer_2
	this.instance = new lib.Bitmap11blower();
	this.instance.setTransform(-75,-106);

	this.shape = new cjs.Shape();
	this.shape.graphics.f().s("#000000").ss(1,1,1).p("AjbhRIG2Cj");
	this.shape.setTransform(30.9,-72.15);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.shape},{t:this.instance}]}).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.blower, new cjs.Rectangle(-75,-106,152,103), null);


