	this.wiring.setTransform(0.65,6.5,1,1,0,0,0,0,0.2);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.wiring},{t:this.komponen},{t:this.lampu}]}).wait(1));

	this._renderFirstFrame();

