(lib.menu = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		var menu_tampil = false;
		
		// Menambahkan event listener pada tombol menu
		this.btn.menu.addEventListener("click", menu.bind(this));
		
		function menu() {
		    menu_tampil = !menu_tampil; // Toggle status menu (true/false)
		    
		    if (menu_tampil) {
		        lihat_menu.call(this);
		    } else {
		        tutup_menu.call(this);
				
		    }
		}
		
		function tutup_menu(){
			this.btn.play(); // Animasi untuk tombol
			exportRoot.menutupPDF(); // menutup Pdf
			
			
		        createjs.Tween.get(this.slide)
		            .to({x: -1500}, 500, createjs.Ease.sineInOut);
			
		}
		function lihat_menu(){
			
			this.btn.play(); // Animasi untuk tombol
		        createjs.Tween.get(this.slide)
		            .to({x: -50}, 500, createjs.Ease.sineInOut); // Slide ke kanan dalam 500ms
		}
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Layer_1
	this.btn = new lib.btn_menu();
	this.btn.name = "btn";
	this.btn.setTransform(0.7,25.85,0.4696,0.4696);

	this.slide = new lib.slide();
	this.slide.name = "slide";
	this.slide.setTransform(-1612.55,-17.35,0.9252,0.9618,0,0,0,-0.1,-0.1);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.slide},{t:this.btn}]}).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.menu, new cjs.Rectangle(-1637.4,-17.2,1669,719.9000000000001), null);


