		this.bolakbalik= function(nama, bolakbalik) {
			  const btn = Button.find(b => b.nama === nama);
			  if (btn) btn.bolakbalik = bolakbalik;
		};
		
			const Button = buttonConfigs.map(cfg => ({
			  nama: cfg.key,
			  color: cfg.color,
			  komp: cfg.komp,
			  tahanan: 0,
			  //nilaiAwal: cfg.nilaiAwal ?? 0,
			  bolakbalik: 0,
			  nilaiAwal: 0,
			  nilai: 0,
			  hitung: 0,
			  hubungan: 0,
			  terminalAwal:0,
			  
			  terminal: this[cfg.key]  // menghubungkan ke MovieClip di stage
			}));
		this.multitester.dataButton = Button; 
		
			// Debug jika ada terminal yang tidak ditemukan
			Button.forEach(btn => {
			  if (!btn.terminal) {
				console.error(`❌ Terminal tidak ditemukan: ${btn.nama}`);
			  }
			});
		
		
		
			Button.forEach(btn => {
				
			  if (!btn.terminal) {
				console.error(`ERROR: terminal tidak ditemukan untuk button ${btn.nama}`);
			  }
			});
		
			let koneksi = [];
			let selectedBtnStart = null;
		
			const garisKoneksi = new createjs.Shape();
			self.addChild(garisKoneksi);
		
			function setupButtonClicks() {
			  Button.forEach(btn => {
				if (!btn.terminal) return;
		
				btn.terminal.cursor = "pointer";
				btn.terminal.on("click", () => {
				  if (!selectedBtnStart) {
					// Pilih tombol sebagai start
					selectedBtnStart = btn;
					console.log("Memulai koneksi dari:", btn.nama);
				  } else {
					const namaStart = selectedBtnStart.nama;
					const namaTarget = btn.nama;
		
					// Ambil nilai awal dengan fallback jika undefined
					const nilaiAwalStart = selectedBtnStart.nilaiAwal ?? 0;
					const nilaiAwalTarget = btn.nilaiAwal ?? 0;
		
					console.log(`Cek koneksi: ${namaStart}(${nilaiAwalStart}) <-> ${namaTarget}(${nilaiAwalTarget})`);
		
					// Cek apakah koneksi sudah ada
					const index = koneksi.findIndex(k =>
					  (k.startNama === namaStart && k.targetNama === namaTarget) ||
					  (k.startNama === namaTarget && k.targetNama === namaStart)
					);
		
					if (index !== -1) {
					  // Hapus koneksi
					  koneksi.splice(index, 1);
					  console.log(`🗑️ Koneksi dihapus: ${namaStart} ↔ ${namaTarget}`);
					} else {
					  // === Larangan 1: Tidak boleh menghubungkan ke diri sendiri ===
					  if (namaStart === namaTarget) {
						console.log("❌ Larangan: Tidak boleh menghubungkan ke tombol yang sama.");
						selectedBtnStart = null;
						return;
					  }
		
					  // === Larangan 2: Tidak boleh hubungkan nilaiAwal 1 dan 12
					  const pasanganDilarang = 
						(nilaiAwalStart === 1 && nilaiAwalTarget === 12) ||
						(nilaiAwalStart === 12 && nilaiAwalTarget === 1);
		
					  if (pasanganDilarang) {
						console.log("❌ Larangan: Tidak boleh menghubungkan nilaiAwal 1 dan 12.");
						selectedBtnStart = null;
						return;
					  }
		
					  // === Larangan 3: Tidak boleh menghubungkan jika start === 1 atau target === 12
					  if (nilaiAwalStart === 1 || nilaiAwalTarget === 12) {
						console.log("❌ Larangan: Tidak boleh menghubungkan jika nilai start adalah 1 atau nilai target adalah 12.");
						selectedBtnStart = null;
						return;
					  }
		
					  // Tambah koneksi baru
					  koneksi.push({
						startNama: namaStart,
						targetNama: namaTarget
					  });
					  console.log(`✅ Terhubung: ${namaStart} → ${namaTarget}`);
					}
		
					updateSemuaTarget();
					drawAllLines();
					selectedBtnStart = null;
				  }
				});
			  });
			}
		
		function drawAllLines() {
		  garisKoneksi.graphics.clear();
		
		  koneksi.forEach(k => {
		    const startBtn = Button.find(b => b.nama === k.startNama);
		    const targetBtn = Button.find(b => b.nama === k.targetNama);
		
		    if (startBtn && targetBtn && startBtn.terminal && targetBtn.terminal) {
		      const globalStart = startBtn.terminal.localToGlobal(0, 0);
		      const globalEnd = targetBtn.terminal.localToGlobal(0, 0);
		      const localStart = self.globalToLocal(globalStart.x, globalStart.y);
		      const localEnd = self.globalToLocal(globalEnd.x, globalEnd.y);
		
		      const controlX = (localStart.x + localEnd.x) / 2;
		
		      // Hitung jarak Euclidean
		      const dx = localEnd.x - localStart.x;
		      const dy = localEnd.y - localStart.y;
		      const distance = Math.sqrt(dx * dx + dy * dy);
		
		      // Faktor lengkung (ubah sesuai kebutuhan)
		      const bendFactor = 0.3;
		
		      // Buat controlY makin turun sesuai jarak
		      const controlY = Math.max(localStart.y, localEnd.y) + distance * bendFactor;
		
		      const warnaGaris = startBtn.color || "#00AAFF";
		
		      const g = garisKoneksi.graphics;
		      g.setStrokeStyle(3)
		       .beginStroke(warnaGaris)
		       .moveTo(localStart.x, localStart.y)
		       .quadraticCurveTo(controlX, controlY, localEnd.x, localEnd.y)
		       .endStroke();
		
		      // --- Tambahkan anak panah di ujung ---
		      const t = 0.95; // dekat dengan 1 (titik akhir)
		      const dxArrow = (1 - t) * (controlX - localStart.x) + t * (localEnd.x - controlX);
		      const dyArrow = (1 - t) * (controlY - localStart.y) + t * (localEnd.y - controlY);
		      const angle = Math.atan2(dyArrow, dxArrow);
		
		      const arrowLength = 10;
		      const arrowAngle = Math.PI / 6; // 30 derajat
		
		      const x1 = localEnd.x - arrowLength * Math.cos(angle - arrowAngle);
		      const y1 = localEnd.y - arrowLength * Math.sin(angle - arrowAngle);
		      const x2 = localEnd.x - arrowLength * Math.cos(angle + arrowAngle);
		      const y2 = localEnd.y - arrowLength * Math.sin(angle + arrowAngle);
		
		      g.setStrokeStyle(3)
		       .beginStroke(warnaGaris)
		       .moveTo(localEnd.x, localEnd.y)
		       .lineTo(x1, y1)
		       .moveTo(localEnd.x, localEnd.y)
		       .lineTo(x2, y2)
		       .endStroke();
		    }
		  });
		
		  stage.update();
		}
		
		
		
		
		
		
		
		function updateSemuaTarget() {
			  // Reset nilai dan hitung
			  Button.forEach(btn => {
				btn.nilai = 0;
				btn.hitung = 0;
			  });
		
			  // Set nilai awal dulu
			  Button.forEach(btn => {
				btn.nilai = btn.nilaiAwal;
			  });
		
			  let changed = true;
			  let iterasi = 0;
			  const maxIterasi = 20;
		
			  while (changed && iterasi < maxIterasi) {
				changed = false;
				iterasi++;
		
				// Temp container nilai baru dan hitung untuk iterasi ini
				const nilaiBaru = {};
				Button.forEach(btn => {
				  nilaiBaru[btn.nama] = { nilai: 0, hitung: 0 };
				});
		
				// Arus POSITIF: dari start ke target
				koneksi.forEach(k => {
				  const start = Button.find(b => b.nama === k.startNama);
				  const target = Button.find(b => b.nama === k.targetNama);
		
				  if (start && target) {
					if (start.nilai >= 6) { // Start menyalurkan nilai
					  nilaiBaru[target.nama].nilai += start.nilai;
					  nilaiBaru[target.nama].hitung += 1;
					}
				  }
				});
		
				// Arus NEGATIF: dari target ke start (balik arah)
				koneksi.forEach(k => {
				  const start = Button.find(b => b.nama === k.startNama);
				  const target = Button.find(b => b.nama === k.targetNama);
		
				  if (start && target) {
					if (target.nilai != 0 && target.nilai <= 1 && start.nilai != -1) { // Target menyalurkan nilai ke start
					  nilaiBaru[start.nama].nilai += target.nilai;
					  nilaiBaru[start.nama].hitung += 1;
					  //hubungan
						if(start.hubungan==0){
						}
						else{target.hubungan = start.hubungan;}
					}
					if (start.nilai == -1) { // Start menyalurkan nilai
					  nilaiBaru[target.nama].nilai += start.nilai+2;
					  nilaiBaru[target.nama].hitung += 1;
						
						target.hubungan = start.hubungan;			
					}
				  
					
				  }
				});
		
				// Update nilai tombol berdasar rata-rata nilaiBaru, atau set ke nilaiAwal jika hitung=0
				Button.forEach(btn => {
				  if (nilaiBaru[btn.nama].hitung > 0) {
					const rata = nilaiBaru[btn.nama].nilai / nilaiBaru[btn.nama].hitung;
					const rataBulatan = Math.round(rata * 10) / 10;
		
					if (btn.nilai !== rataBulatan) {
					  btn.nilai = rataBulatan;
					  changed = true;
					}
				  } else {
					if (btn.nilai !== btn.nilaiAwal) {
					  btn.nilai = btn.nilaiAwal;
					  changed = true;
					}
				  }
		
				  // Jika nilai 0 maka dianggap putus koneksi, bisa juga clear nilai atau flag lain
				  if (btn.nilai === 0) {
					// Optional: bisa beri efek khusus kalau mau
				  }
				});
			  }
		
			  // Salin nilai ke masing-masing terminal (MovieClip)
			  Button.forEach(btn => {
				if (btn.terminal) {
				  btn.terminal.nilai = btn.nilai;
				  btn.terminal.hubungan = btn.hubungan;
					
				}
			  });
		
			  //console.log("=== NILAI BUTTON (Positif & Negatif) ===");
			  Button.forEach(btn => {
				//console.log(`${btn.nama} = ${btn.tahanan}`);
			    //console.log(`${btn.nama} = ${btn.komp}`);
				//console.log(`${btn.nama} = ${btn.nilai}`);
				//console.log(`hubungan ${btn.nama} = ${btn.hubungan}`);
				//console.log(`timer ${btn.nama} = ${btn.timer}`);
			  });
			  //console.log("========================================");
		
			  stage.update();
			  updateAnimations();
			  if(self.status_ulang == true){
						 self.ulang();
					 }
		
			}
		
		
		
			setupButtonClicks();
		
		
			// Simpan semua animasi aktif supaya bisa dihapus
			let activeFlowsData = [];
		
			// Fungsi untuk menambahkan animasi flow ke list
		function addAnimasiFlowData(startX, startY, endX, endY, color) {
			  const controlX = (startX + endX) / 2;
		
			  // Hitung jarak antara dua titik (secara Euclidean)
			  const dx = endX - startX;
			  const dy = endY - startY;
			  const distance = Math.sqrt(dx * dx + dy * dy);
		
			  // Semakin jauh jaraknya, semakin besar lengkung ke bawah (maksimal dikontrol dengan faktor multiplier)
			  const bendFactor = 0.3; // ubah sesuai keinginan efek lengkung
			  const controlY = Math.max(startY, endY) + distance * bendFactor;
		
			  activeFlowsData.push({
				startX, startY, endX, endY, controlX, controlY, color, dashOffset: 0
			  });
		}
		
			// Hapus flow yang tidak relevan, bukan semua
		function clearFlows(newData) {
			  activeFlowsData = activeFlowsData.filter(existing => {
				return newData.some(newFlow =>
				  existing.startX === newFlow.startX &&
				  existing.startY === newFlow.startY &&
				  existing.endX === newFlow.endX &&
				  existing.endY === newFlow.endY &&
				  existing.color === newFlow.color
				);
			  });
			}
		
			// Buat satu Shape untuk menggambar semua flow sekaligus
			const flowShape = new createjs.Shape();
			stage.addChild(flowShape);
		
			// Satu ticker global untuk menggambar semua flow
			createjs.Ticker.framerate = 60;
			createjs.Ticker.on("tick", function() {
			  flowShape.graphics.clear();
		
			  activeFlowsData.forEach(flow => {
				// Update dash offset untuk animasi strip bergerak
				flow.dashOffset -= 1;
				if (flow.dashOffset <= -25) { // dashLength+gapLength = 15+10 =25
				  flow.dashOffset = 0;
				}
		
				flowShape.graphics
				  .setStrokeStyle(3, "round")
				  .beginStroke(flow.color)
				  .setStrokeDash([15, 10], flow.dashOffset)
				  .moveTo(flow.startX, flow.startY)
				  .curveTo(flow.controlX, flow.controlY, flow.endX, flow.endY);
			  });
		
			  stage.update();
			});
		
			// Update animasi berdasarkan nilai tombol
		function updateAnimations() {
			  const newFlows = [];
		
			  koneksi.forEach(k => {
				const startBtn = Button.find(b => b.nama === k.startNama);
				const targetBtn = Button.find(b => b.nama === k.targetNama);
		
				if (startBtn && targetBtn && startBtn.terminal && targetBtn.terminal) {
				  const globalStart = startBtn.terminal.localToGlobal(0, 0);
				  const globalEnd = targetBtn.terminal.localToGlobal(0, 0);
				  const localStart = stage.globalToLocal(globalStart.x, globalStart.y);
				  const localEnd = stage.globalToLocal(globalEnd.x, globalEnd.y);
		
				let color = null;
				let colorbalik = null;
		
				if (startBtn.nilai >= 6 && self.status_arus === true) {
				  color = "#FFFF00";
				} else if (
				  startBtn.nilai != 0 &&
				  startBtn.nilai <= 1 &&
				  startBtn.hubungan == 1 &&
				  targetBtn.hubungan == 1 &&
				  self.status_arus === true
				) {
				  color = "#00FF00";
				} else if (
				  targetBtn.nilai == 1 &&
				  targetBtn.bolakbalik == 1 &&
				  self.status_arus === true
				) {
				  colorbalik = "#00FF00";
				}
		
				if (color) {
				  newFlows.push({
					startX: localStart.x,
					startY: localStart.y,
					endX: localEnd.x,
					endY: localEnd.y,
					color: color
				  });
				}
		
				if (colorbalik) {
				  newFlows.push({
					startX: localEnd.x, // dibalik
					startY: localEnd.y,
					endX: localStart.x,
					endY: localStart.y,
					color: colorbalik
				  });
				}
		
				}
			  });
		
			  // Bersihkan hanya flow yang sudah tidak aktif
			  clearFlows(newFlows);
		
			  // Tambahkan flow baru yang belum ada
			  newFlows.forEach(flow => {
				const exists = activeFlowsData.some(existing =>
				  existing.startX === flow.startX &&
				  existing.startY === flow.startY &&
				  existing.endX === flow.endX &&
				  existing.endY === flow.endY &&
				  existing.color === flow.color
				);
		
				if (!exists) {
				  addAnimasiFlowData(
					flow.startX,
					flow.startY,
					flow.endX,
					flow.endY,
					flow.color
				  );
				}
			  });
			}
		
		
		
